expected.annotated:
{
  "$schema": "https://calm.finos.org/release/1.2/meta/calm.json",
  "unique-id": "calm-shop",
  "metadata": [
    {
      "description": "A shop that finds homes for pets: it registers each pet with a Petstore API and publishes each adoption on a Kafka topic, which an audit reads back. The wiring of each environment is in shop.decorators.json."
    }
  ],
  "nodes": [
    {
      "unique-id": "calm-shop",
      "node-type": "system",
      "name": "Calm shop",
      "description": "The shop and the dependencies it reaches."
    },
    {
      "unique-id": "adoptions-service",
      "node-type": "service",
      "name": "Adoptions service [shop.adoptions 0.1.0]",
      "description": "Registers each adopted pet and publishes the adoption (example.com/calm-shop, cmd/shop).",
      "metadata": [
        {
          "ironframe-binding": {
            "environment": "twin",
            "contract": {
              "package": "shop.adoptions",
              "version": "0.1.0"
            },
            "deployment": {
              "deployment": "external"
            }
          }
        }
      ]
    },
    {
      "unique-id": "adoptions-audit",
      "node-type": "service",
      "name": "Adoptions audit [shop.adoptions 0.1.0]",
      "description": "Reads adoptions back from the log (example.com/calm-shop, cmd/shop audit).",
      "metadata": [
        {
          "ironframe-binding": {
            "environment": "twin",
            "contract": {
              "package": "shop.adoptions",
              "version": "0.1.0"
            },
            "deployment": {
              "deployment": "process",
              "command": [
                "go",
                "run",
                "./cmd/shop",
                "audit"
              ],
              "dir": "../app"
            }
          }
        }
      ]
    },
    {
      "unique-id": "adoptions-log",
      "node-type": "message-broker",
      "name": "Adoptions log [twin lawtwin/kafka:0.1.0 (answers)]",
      "description": "The Kafka cluster holding the adoptions topic, shared by the service and the audit.",
      "interfaces": [
        {
          "unique-id": "adoptions-log-bootstrap",
          "host": "kafka",
          "port": 9092
        }
      ],
      "metadata": [
        {
          "ironframe-binding": {
            "environment": "twin",
            "kind": "twin",
            "binding": "twin lawtwin/kafka:0.1.0 (answers)",
            "contract": {
              "package": "lawtwin.kafka",
              "version": ">=0.1.0, <0.2.0",
              "abilities": [
                "lawtwin.kafka::ability::Broker"
              ]
            }
          }
        }
      ]
    },
    {
      "unique-id": "pet-registry",
      "node-type": "service",
      "name": "Pet registry [twin lawtwin/http:0.1.0 (conformant)]",
      "description": "A Petstore API the service registers pets with.",
      "interfaces": [
        {
          "unique-id": "pet-registry-api",
          "url": "/pet"
        }
      ],
      "metadata": [
        {
          "ironframe-binding": {
            "environment": "twin",
            "kind": "twin",
            "binding": "twin lawtwin/http:0.1.0 (conformant)",
            "contract": {
              "package": "lawtwin.petstore",
              "version": "^0.1",
              "abilities": [
                "lawtwin.petstore::ability::PetApi"
              ]
            }
          }
        }
      ]
    }
  ],
  "relationships": [
    {
      "unique-id": "service-publishes-adoptions",
      "description": "The service publishes each adoption on the adoptions topic.",
      "protocol": "TCP",
      "relationship-type": {
        "connects": {
          "source": {
            "node": "adoptions-service"
          },
          "destination": {
            "node": "adoptions-log",
            "interfaces": [
              "adoptions-log-bootstrap"
            ]
          }
        }
      }
    },
    {
      "unique-id": "service-registers-pets",
      "description": "The service registers each pet and reads its name back.",
      "protocol": "HTTP",
      "relationship-type": {
        "connects": {
          "source": {
            "node": "adoptions-service"
          },
          "destination": {
            "node": "pet-registry",
            "interfaces": [
              "pet-registry-api"
            ]
          }
        }
      }
    },
    {
      "unique-id": "audit-reads-adoptions",
      "description": "The audit reads adoptions back from the same topic.",
      "protocol": "TCP",
      "relationship-type": {
        "connects": {
          "source": {
            "node": "adoptions-audit"
          },
          "destination": {
            "node": "adoptions-log",
            "interfaces": [
              "adoptions-log-bootstrap"
            ]
          }
        }
      }
    },
    {
      "unique-id": "calm-shop-composition",
      "relationship-type": {
        "composed-of": {
          "container": "calm-shop",
          "nodes": [
            "adoptions-service",
            "adoptions-audit",
            "adoptions-log",
            "pet-registry"
          ]
        }
      }
    }
  ]
}

